// supabase-functions/_shared/reportTemplate.ts
//
// ETAPA 3 — Relatório HTML.
// Componente puro (sem I/O, sem chamadas de rede): recebe os dados da
// empresa + o JSON do diagnóstico (gerado na Etapa 2) e devolve uma
// página HTML completa e autocontida (CSS embutido, logo embutida em
// base64 — sem dependências externas de arquivo).
//
// Não gera PDF. Não envia WhatsApp. Apenas monta o HTML.
// É usado pela Edge Function `generateDiagnosis`, que salva o resultado
// na coluna `diagnostics.html`.

// Company e DiagnosisResult agora vêm do módulo de tipos compartilhado
// (antes eram interfaces duplicadas aqui como ReportCompany/ReportDiagnosis).
import { Company, DiagnosisResult } from './types.ts';

export interface BuildReportInput {
  company: Company;
  diagnosis: DiagnosisResult;
  generatedAt?: Date;
  /**
   * Link do botão "Agendar Consultoria". Ajuste para o link real
   * (Calendly, WhatsApp, etc.) antes de publicar em produção.
   */
  scheduleUrl?: string;
}

// Logo em base64 (mesma logo usada no index.html), para o relatório
// nunca depender de um arquivo de imagem externo.
const LOGO_BASE64 = "";

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function listItems(items: string[]): string {
  if (!items || items.length === 0) return '<li class="empty">Nenhum item informado.</li>';
  return items.map((item) => `<li>${escapeHtml(item)}</li>`).join("\n          ");
}

// 0-25 Inicial · 26-50 Em Estruturação · 51-75 Em Crescimento · 76-100 Avançado
// (visual complementar ao "nivel" retornado pela IA — calculado a partir
// do próprio score, sem inventar nenhuma informação nova)
function maturityStageIndex(score: number): number {
  if (score <= 25) return 0;
  if (score <= 50) return 1;
  if (score <= 75) return 2;
  return 3;
}

export function buildDiagnosticReportHtml({
  company,
  diagnosis,
  generatedAt = new Date(),
  scheduleUrl = "https://wa.me/5561984012782?text=Ol%C3%A1!%20Vim%20do%20meu%20diagn%C3%B3stico%20e%20quero%20agendar%20uma%20consultoria.",
}: BuildReportInput): string {
  const empresa = escapeHtml(company.empresa || "Sua empresa");
  const nome = escapeHtml(company.nome || "");
  const dataFormatada = generatedAt.toLocaleDateString("pt-BR", {
    day: "2-digit",
    month: "long",
    year: "numeric",
  });

  const score = Math.max(0, Math.min(100, Math.round(diagnosis.score ?? 0)));
  const nivel = escapeHtml(diagnosis.nivel || "");
  const stageNames = ["Inicial", "Em Estruturação", "Em Crescimento", "Avançado"];
  const activeStage = maturityStageIndex(score);

  const maturityStagesHtml = stageNames
    .map((label, i) => {
      const state = i < activeStage ? "done" : i === activeStage ? "active" : "";
      return `
        <div class="stage ${state}">
          <span class="stage-dot"></span>
          <span class="stage-label">${label}</span>
        </div>`;
    })
    .join("");

  return `<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Diagnóstico Empresarial — ${empresa}</title>
<meta name="robots" content="noindex, nofollow">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Manrope:wght@700;800&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
  :root{
    --navy-900:#062B45; --navy-800:#0B3A5C; --navy-700:#134266;
    --sky-400:#7DB0E3; --sky-300:#9AC3EA; --sky-100:#EAF3FC; --sky-50:#F7FBFF;
    --slate-600:#5B6B7A; --border-soft:#E4EDF6;
    --gold-500:#C9A227; --gold-400:#E4C158; --gold-600:#A9841D;
    --danger:#B3261E; --success:#1E8E5A;
  }
  *{box-sizing:border-box;}
  body{
    margin:0; font-family:'Inter',system-ui,sans-serif; color:var(--navy-900);
    background:var(--sky-50); line-height:1.55;
  }
  h1,h2,h3,.display{font-family:'Manrope',system-ui,sans-serif;}
  .wrap{ max-width:820px; margin:0 auto; padding:0 1.25rem 4rem; }

  /* Header */
  .report-header{
    background:linear-gradient(160deg, var(--navy-900) 0%, var(--navy-800) 55%, var(--navy-700) 100%);
    padding:2.5rem 1.25rem 3rem; text-align:center; color:#fff;
  }
  .report-header img{ height:44px; width:auto; margin-bottom:1.25rem; }
  .report-header h1{ font-size:1.6rem; font-weight:800; margin:0 0 0.4rem; }
  .report-header p{ margin:0; color:var(--sky-300); font-size:0.95rem; }
  .meta-row{
    display:flex; justify-content:center; gap:1.5rem; margin-top:1.5rem;
    font-size:0.85rem; color:#D6E7F8; flex-wrap:wrap;
  }

  /* Cards */
  .card{
    background:#fff; border:1px solid var(--border-soft); border-radius:20px;
    padding:1.75rem; margin-top:-2.25rem; position:relative; z-index:2;
    box-shadow:0 12px 30px -18px rgba(6,43,69,0.25);
  }
  .card + .card{ margin-top:1.5rem; }
  .card h2{ font-size:1.15rem; font-weight:800; margin:0 0 1rem; color:var(--navy-900); }
  .card h2 .icon{ margin-right:0.4rem; }

  /* Score */
  .score-card{ text-align:center; }
  .score-number{ font-family:'Manrope',sans-serif; font-weight:800; font-size:3rem; color:var(--navy-900); line-height:1; }
  .score-number span{ font-size:1.25rem; color:var(--slate-600); font-weight:700; }
  .score-level{
    display:inline-block; margin-top:0.5rem; padding:0.3rem 0.9rem; border-radius:999px;
    background:var(--sky-100); color:var(--navy-800); font-weight:700; font-size:0.85rem;
  }
  .progress-track{ width:100%; height:12px; border-radius:999px; background:var(--sky-100); overflow:hidden; margin-top:1.25rem; }
  .progress-fill{ height:100%; border-radius:999px; background:linear-gradient(90deg, var(--navy-900), var(--sky-400)); }

  /* Maturity stages */
  .stages{ display:flex; justify-content:space-between; margin-top:1.5rem; position:relative; }
  .stages::before{
    content:''; position:absolute; top:7px; left:0; right:0; height:2px; background:var(--border-soft); z-index:0;
  }
  .stage{ position:relative; z-index:1; display:flex; flex-direction:column; align-items:center; gap:0.5rem; flex:1; }
  .stage-dot{ width:16px; height:16px; border-radius:50%; background:#fff; border:2.5px solid var(--border-soft); }
  .stage.done .stage-dot{ background:var(--sky-400); border-color:var(--sky-400); }
  .stage.active .stage-dot{ background:var(--navy-900); border-color:var(--navy-900); box-shadow:0 0 0 4px var(--sky-100); }
  .stage-label{ font-size:0.75rem; color:var(--slate-600); text-align:center; font-weight:600; }
  .stage.active .stage-label{ color:var(--navy-900); }

  p.body-text{ color:var(--slate-600); font-size:0.975rem; margin:0; }

  /* Lists */
  ul.report-list{ margin:0; padding:0; list-style:none; }
  ul.report-list li{
    padding:0.65rem 0 0.65rem 1.9rem; position:relative; font-size:0.95rem; color:var(--navy-900);
    border-bottom:1px solid var(--border-soft);
  }
  ul.report-list li:last-child{ border-bottom:none; }
  ul.report-list li.empty{ color:var(--slate-600); font-style:italic; }
  .list-fortes li::before{ content:'✓'; position:absolute; left:0; color:var(--success); font-weight:800; }
  .list-fracos li::before{ content:'!'; position:absolute; left:0.3rem; color:var(--danger); font-weight:800; }
  .list-oportunidades li::before{ content:'→'; position:absolute; left:0; color:var(--sky-400); font-weight:800; }

  /* Action plan */
  .plan-grid{ display:grid; grid-template-columns:1fr; gap:1.25rem; }
  @media(min-width:700px){ .plan-grid{ grid-template-columns:repeat(3,1fr); } }
  .plan-col{ background:var(--sky-50); border:1px solid var(--border-soft); border-radius:16px; padding:1.25rem; }
  .plan-col h3{ font-size:0.9rem; font-weight:800; color:var(--navy-800); margin:0 0 0.75rem; text-transform:uppercase; letter-spacing:0.03em; }
  .plan-col ul{ margin:0; padding-left:1.1rem; font-size:0.875rem; color:var(--navy-900); }
  .plan-col li{ margin-bottom:0.5rem; }

  /* CTA */
  .cta-card{ text-align:center; background:linear-gradient(160deg, var(--navy-900), var(--navy-700)); color:#fff; }
  .cta-card h2{ color:#fff; }
  .cta-card p.body-text{ color:var(--sky-100); margin-bottom:1.5rem; }
  .cta-btn{
    display:inline-flex; align-items:center; gap:0.5rem; font-weight:700; font-size:1rem;
    padding:1rem 2rem; border-radius:14px; text-decoration:none;
    background:linear-gradient(135deg, var(--gold-400), var(--gold-500)); color:var(--navy-900);
    box-shadow:0 10px 24px -10px rgba(201,162,39,0.65);
  }

  footer{ text-align:center; padding:2rem 1rem 0; color:var(--slate-600); font-size:0.8rem; }

  @media print{
    body{ background:#fff; }
    .card{ box-shadow:none; border:1px solid var(--border-soft); }
  }
</style>
</head>
<body>

<div class="report-header">
  <img src="data:image/png;base64,${LOGO_BASE64}" alt="Branding Soluções">
  <h1>Relatório de Diagnóstico Empresarial</h1>
  <p>${empresa}${nome ? ` · ${nome}` : ""}</p>
  <div class="meta-row">
    <span>📅 ${dataFormatada}</span>
    ${company.segmento ? `<span>🏷️ ${escapeHtml(company.segmento)}</span>` : ""}
    ${company.cidade || company.estado ? `<span>📍 ${escapeHtml([company.cidade, company.estado].filter(Boolean).join(" - "))}</span>` : ""}
  </div>
</div>

<div class="wrap">

  <div class="card score-card">
    <div class="score-number">${score}<span>/100</span></div>
    <div class="score-level">${nivel}</div>
    <div class="progress-track"><div class="progress-fill" style="width:${score}%;"></div></div>
  </div>

  <div class="card">
    <h2><span class="icon">📋</span>Resumo Executivo</h2>
    <p class="body-text">${escapeHtml(diagnosis.resumo || "")}</p>
  </div>

  <div class="card">
    <h2><span class="icon">📈</span>Maturidade Digital</h2>
    <div class="stages">${maturityStagesHtml}</div>
  </div>

  <div class="card">
    <h2><span class="icon">💪</span>Pontos Fortes</h2>
    <ul class="report-list list-fortes">
          ${listItems(diagnosis.pontosFortes)}
    </ul>
  </div>

  <div class="card">
    <h2><span class="icon">⚠️</span>Pontos Fracos</h2>
    <ul class="report-list list-fracos">
          ${listItems(diagnosis.pontosFracos)}
    </ul>
  </div>

  <div class="card">
    <h2><span class="icon">🚀</span>Oportunidades</h2>
    <ul class="report-list list-oportunidades">
          ${listItems(diagnosis.oportunidades)}
    </ul>
  </div>

  <div class="card">
    <h2><span class="icon">🗓️</span>Plano de Ação</h2>
    <div class="plan-grid">
      <div class="plan-col">
        <h3>30 dias</h3>
        <ul>${diagnosis.plano30dias.map((i) => `<li>${escapeHtml(i)}</li>`).join("")}</ul>
      </div>
      <div class="plan-col">
        <h3>60 dias</h3>
        <ul>${diagnosis.plano60dias.map((i) => `<li>${escapeHtml(i)}</li>`).join("")}</ul>
      </div>
      <div class="plan-col">
        <h3>90 dias</h3>
        <ul>${diagnosis.plano90dias.map((i) => `<li>${escapeHtml(i)}</li>`).join("")}</ul>
      </div>
    </div>
  </div>

  <div class="card">
    <h2><span class="icon">✅</span>Conclusão</h2>
    <p class="body-text">${escapeHtml(diagnosis.conclusao || "")}</p>
  </div>

  <div class="card cta-card">
    <h2>Pronto para colocar esse plano em prática?</h2>
    <p class="body-text">Fale com nossa equipe e agende uma consultoria estratégica gratuita.</p>
    <a href="${scheduleUrl}" target="_blank" rel="noopener" class="cta-btn">📅 Agendar Consultoria</a>
  </div>

  <footer>© ${generatedAt.getFullYear()} Branding Soluções. Relatório gerado automaticamente.</footer>
</div>

</body>
</html>`;
}
